mapper.select:
SELECT cr.ID_CONSTANCIA_RETENCION AS idConstanciaRetencion, cr.NOMBRE_EMISOR AS nombreEmisor, cr.RUC_EMISOR AS rucEmisor, cr.NOMBRE_PROVEEDOR AS nombreProveedor, cr.RUC_PROVEEDOR AS rucProveedor, cr.NRO_RETENCION AS nroRetencion, crd.NRO_FACTURA AS nroFactura, crd.TOTAL_FACTURA AS totalFactura, crd.NETO_PAGADO AS neto, crd.RETENCION AS retencion, crd.MONEDA_CONVERTIDA AS monedaRetencion, to_char(cr.FECHA_DOC, 'yyyy-MM-dd') AS fechaDoc FROM CONSTANCIA_RETENCION cr INNER JOIN CONSTANCIA_RETENCION_DETALLE crd ON cr.ID_CONSTANCIA_RETENCION = crd.ID_CONSTANCIA_RETENCION WHERE 1 = 1
AND cr.NOMBRE_PROVEEDOR LIKE '%' || #{nombreProveedor} ||'%'
AND cr.FECHA_DOC >= #{fechaInicio}
AND cr.FECHA_DOC <= #{fechaFin}
AND cr.NRO_RETENCION LIKE '%' || #{nroRetencion} || '%'
AND cr.RUC_PROVEEDOR LIKE '%' || #{rucProveedor} || '%'
ORDER BY cr.FECHA_DOC DESC;
